uniform float texture_size;

uniform sampler2D tex;

flat in vec4 tint;
smooth in vec2 uv;

#if defined(FADED) || defined(CLIPPED) || defined(SUBPIXEL_INTERP)
smooth in float view_position_x;
#endif

#ifdef FADED
flat in float fade_start;
flat in float fade_end;
#endif

#ifdef CLIPPED
flat in float clip_start;
flat in float clip_end;
#endif

#ifdef SUBPIXEL_INTERP
#ifdef COLORED
    #error "Cannot be colored and subpixel interpolated"
#endif
flat in float subpixel_x;
flat in float left_edge_x;
flat in float right_edge_x;
#endif

#if defined(NO_THREE_CHANNEL_ALPHA)
out vec4 frag_color;
#else
layout(location = 0, index = 0) out vec4 frag_color;
layout(location = 0, index = 1) out vec4 frag_alpha;
#endif

void main()
{
#if defined(COLORED)
    vec4 color = texture(tex, uv) * tint.a;
    vec4 alpha = vec4(color.a);
#elif defined(SUBPIXEL_INTERP)
    // Take two samples, one for this pixel and another for the pixel to the
    // left. These need to be zeroed out if they're outside the glyph.
    float is_inside_right = step(ceil(view_position_x), right_edge_x);
    vec4 sample1 = texture(tex, uv) * is_inside_right;

    float is_inside_left = step(left_edge_x, floor(view_position_x));
    vec4 sample2 = texture(tex, uv - vec2(1/texture_size, 0)) * is_inside_left;

    // Mix the two samples by the subpixel position
    vec4 color = tint;
    vec4 alpha = mix(sample1, sample2, subpixel_x) * tint.a;
#else
    vec4 color = tint;
    vec4 alpha = texture(tex, uv) * tint.a;
#endif

#ifdef FADED
    alpha *= 1 - smoothstep(fade_start, fade_end, view_position_x);
#endif

#ifdef CLIPPED
    alpha *= step(clip_start, view_position_x) * step(view_position_x, clip_end);
#endif

#if defined(NO_THREE_CHANNEL_ALPHA)
    frag_color = color * alpha.g;
#else
    frag_color = color;
    frag_alpha = alpha;
#endif
}

uniform samplerBuffer instances;

uniform vec2 viewport;

#if defined(TEXTURED) && !defined(REPEAT)
uniform vec2 texture_size;
#endif

// a_position is in range 0,1
layout (location = 0) in vec2 a_position;

flat out vec4 tint;

#ifdef TEXTURED
#ifdef REPEAT
smooth out vec2 local_position;
flat out vec2 size;
flat out vec2 texture_source_position;
flat out vec2 texture_source_size;
#else
smooth out vec2 uv;
#endif
#endif

void main()
{
#if !defined(TEXTURED)
    tint = texelFetch(instances, gl_InstanceID * 2 + 0);
    vec4 position_and_size = texelFetch(instances, gl_InstanceID * 2 + 1);
#else
    tint = texelFetch(instances, gl_InstanceID * 3 + 0);
    vec4 position_and_size = texelFetch(instances, gl_InstanceID * 3 + 1);
    vec4 texture_source_position_and_size = texelFetch(instances, gl_InstanceID * 3 + 2);

#if !defined(REPEAT)
    vec2 texture_source_position;
    vec2 texture_source_size;
#endif
    texture_source_position = texture_source_position_and_size.xy;
    texture_source_size = texture_source_position_and_size.zw;
#endif

#if !defined(REPEAT)
    vec2 size;
#endif
    vec2 position = position_and_size.xy;
    size = position_and_size.zw;

#if defined(TEXTURED) && !defined(REPEAT)
    // Use a_position as a texture coord here
    vec2 texture_position = texture_source_position + a_position * texture_source_size;
    uv = texture_position / texture_size;
#endif

#if !defined(REPEAT)
    vec2 local_position;
#endif
    local_position = a_position * size;
    vec2 view_position = position + local_position;
    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

