uniform vec2 viewport;
uniform vec2 position;
uniform vec2 size;
uniform float checkerboard_size;

// a_position is in range 0,1
layout (location = 0) in vec2 a_position;

smooth out vec2 uv;

void main()
{
    vec2 local_position = a_position * size;

    uv = local_position / checkerboard_size;

    vec2 view_position = position + local_position;
    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

// a_position is in range 0,1
layout (location = 0) in vec2 a_position;

uniform vec2 viewport;
uniform float texture_size;

uniform samplerBuffer instances;

flat out vec4 tint;
smooth out vec2 uv;

#if defined(FADED) || defined(CLIPPED) || defined(SUBPIXEL_INTERP)
smooth out float view_position_x;
#endif

#ifdef FADED
flat out float fade_start;
flat out float fade_end;
#endif

#ifdef CLIPPED
flat out float clip_start;
flat out float clip_end;
#endif

#ifdef SUBPIXEL_INTERP
flat out float subpixel_x;
flat out float left_edge_x;
flat out float right_edge_x;
#endif

void main()
{
    vec4 color = texelFetch(instances, gl_InstanceID * 3 + 0);
    vec4 position_and_size = texelFetch(instances, gl_InstanceID * 3 + 1);
    vec4 texture_source_position_and_extra = texelFetch(instances, gl_InstanceID * 3 + 2);

    // Unpack uniform block
    tint = color;
    vec2 position = position_and_size.xy;
    vec2 size = position_and_size.zw;
    vec2 texture_source_position = texture_source_position_and_extra.xy;

#ifdef SUBPIXEL_INTERP
    // To properly interpolate on subpixels we need to draw an extra pixel to
    // the right and position the glyph on the lower pixel boundry. The pixel
    // shader will then interpolate based on the subpixel position.
    left_edge_x = position.x;
    right_edge_x = left_edge_x + size.x;
    subpixel_x = position.x - floor(position.x);

    position.x = floor(position.x);
    size.x += 1;
#endif

#ifdef FADED
    fade_start = texture_source_position_and_extra.z;
    fade_end = texture_source_position_and_extra.w;
#endif

#ifdef CLIPPED
    clip_start = texture_source_position_and_extra.z;
    clip_end = texture_source_position_and_extra.w;
#endif

    // Use a_position as a texture coord here
    vec2 texture_position = texture_source_position + a_position * size;
    uv = texture_position / texture_size;

    vec2 view_position = position + a_position * size;

#if defined(FADED) || defined(CLIPPED) || defined(SUBPIXEL_INTERP)
    view_position_x = view_position.x;
#endif

    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

uniform samplerBuffer instances;

uniform vec2 viewport;
// uniform mat3x2 transform;

// a_position is in range 0,1
layout (location = 0) in vec2 a_position;

flat out vec4 tint;

#ifdef STIPPLED
flat out float stipple_length;
flat out float stipple_on_length;

smooth out float stipple_pos;
#endif

#ifdef SQUIGGLE
flat out float width;

smooth out vec2 line_pos;
#endif

#ifdef ANTIALIAS
#error "Not supported for regular lines"
#endif

void main()
{
#ifdef STIPPLED
    tint = texelFetch(instances, gl_InstanceID * 4 + 0);
    vec4 mat0 = texelFetch(instances, gl_InstanceID * 4 + 1);
    vec4 mat1 = texelFetch(instances, gl_InstanceID * 4 + 2);
    vec4 stipple = texelFetch(instances, gl_InstanceID * 4 + 3);

    float line_length = stipple.x;
    float stipple_offset = stipple.y;
    stipple_length = stipple.z;
    stipple_on_length = stipple.w;
#else
    tint = texelFetch(instances, gl_InstanceID * 3 + 0);
    vec4 mat0 = texelFetch(instances, gl_InstanceID * 3 + 1);
    vec4 mat1 = texelFetch(instances, gl_InstanceID * 3 + 2);

#ifdef SQUIGGLE
    width = mat1.b;
    float line_length = mat1.a;
#endif
#endif

    mat3x2 transform = mat3x2(mat0.rg, mat0.ba, mat1.rg);

    vec2 view_position = (transform * vec3(a_position, 1)).xy;

#ifdef SQUIGGLE
    line_pos = vec2(a_position.x * line_length, a_position.y * width);
#endif

#ifdef STIPPLED
    stipple_pos = (stipple_offset + a_position.x * line_length) / stipple_length;
#endif

    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

uniform samplerBuffer instances;

uniform vec2 viewport;

uniform uint segments;

// a_position.y is in range 0,1
// a_position.x goes from 0 til the number of segments
layout (location = 0) in vec2 a_position;

flat out vec4 tint;

#ifdef STIPPLED
flat out float stipple_length;
flat out float stipple_on_length;

smooth out float stipple_pos;
#endif

#ifdef ANTIALIAS
#define ANTIALIAS_FEATHER 0.5

flat out float width;

smooth out float local_x;
#endif

vec2 perpendicular(vec2 v)
{
    return vec2(-v.y, v.x);
}

void main()
{
#if !defined(ANTIALIAS)
    float width;
#endif

#ifdef STIPPLED
    tint = texelFetch(instances, gl_InstanceID * 5 + 0);
    vec4 points_0_and_1 = texelFetch(instances, gl_InstanceID * 5 + 1);
    vec4 points_2_and_3 = texelFetch(instances, gl_InstanceID * 5 + 2);
    width = texelFetch(instances, gl_InstanceID * 5 + 3).r;
    vec4 stipple = texelFetch(instances, gl_InstanceID * 5 + 4);

    float line_length = stipple.x;
    float stipple_offset = stipple.y;
    stipple_length = stipple.z;
    stipple_on_length = stipple.w;
#else
    tint = texelFetch(instances, gl_InstanceID * 4 + 0);
    vec4 points_0_and_1 = texelFetch(instances, gl_InstanceID * 4 + 1);
    vec4 points_2_and_3 = texelFetch(instances, gl_InstanceID * 4 + 2);
    width = texelFetch(instances, gl_InstanceID * 4 + 3).r;
#endif

    vec2 point0 = points_0_and_1.xy;
    vec2 point1 = points_0_and_1.zw;
    vec2 point2 = points_2_and_3.xy;
    vec2 point3 = points_2_and_3.zw;

    float t = a_position.x / segments;
    float nt = 1 - t;

    // Hard maths
    vec2 bezier_point = point0 * nt * nt * nt + 3.0 * point1 * nt * nt * t + 3.0 * point2 * nt * t * t + point3 * t * t * t;

    vec2 tangent = -3.0 * point0 * nt * nt + 3.0 * point1 * (1.0 - 4.0 * t + 3.0 * t * t) + 3.0 * point2 * (2.0 * t - 3.0 * t * t) + 3.0 * point3 * t * t;

    vec2 normal = perpendicular(tangent);

#ifdef ANTIALIAS
    float half_width = width / 2 + ANTIALIAS_FEATHER;
#else
    float half_width = width / 2;
    float local_x;
#endif
    local_x = (a_position.y * 2 - 1) * half_width;

    // Offset from y to give it width
    vec2 view_position = bezier_point + local_x * normalize(normal);

#ifdef STIPPLED
    stipple_pos = (stipple_offset + t * line_length) / stipple_length;
#endif

    vec2 clip_space_position = (view_position / viewport) * 2 - 1;
    gl_Position = vec4(clip_space_position, 0, 1);
}

